def read_lines(lines):
    for line in lines:
        text = line.strip()
        if not text or text.startswith('#'):
            continue
        yield text


def countdown(n):
    while n > 0:
        yield n
        n -= 1


raw = ['  host = localhost  ', '', '# 这是注释', 'port = 8080', '   ', 'debug = True']
kept = list(read_lines(raw))
print(len(kept), kept)
